import numpy as np
L=6
word=0
for family in (0,1):
 for y in range(L):
  for x in range(L):
   if x%2==0 and (x+y)%2==family:
    jx=(x+1)%L if family==0 else (x-1)%L
    jy=(y+1)%L
    word |= 1 << (jx+L*jy)
words=np.array([word],dtype=np.int64)
assert np.allclose(compute_ssm_projection_amplitudes(words.copy(),L), target)

